import{_ as e,o as a,c as r,a2 as d}from"./chunks/framework.il0noOp3.js";const A=JSON.parse('{"title":"WAF — enumerated source for the SAP on Azure workload assessment","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/waf-sap-workload-checklist.md","filePath":"frameworks/waf-sap-workload-checklist.md"}'),s={name:"frameworks/waf-sap-workload-checklist.md"};function o(n,t,i,c,l,h){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="waf-—-enumerated-source-for-the-sap-on-azure-workload-assessment" tabindex="-1">WAF — enumerated source for the SAP on Azure workload assessment <a class="header-anchor" href="#waf-—-enumerated-source-for-the-sap-on-azure-workload-assessment" aria-label="Permalink to &quot;WAF — enumerated source for the SAP on Azure workload assessment&quot;">​</a></h1><p><strong>Enumerated 2026-11-25. Verification method and limits are stated below — read them before quoting any coverage number from this page.</strong></p><p>This page enumerates the review that Microsoft publishes as <a href="https://learn.microsoft.com/en-us/assessments/b45998e4-8e92-41b1-a0bd-ab07e665db64/" target="_blank" rel="noreferrer">SAP on Azure | Well-Architected Review</a>, for SAP running on Azure virtual machines. <code>src/assess/rules/waf.sap.yaml</code> is written against this page only, and every rule cites an item number from the tables below.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Assessment</td><td><a href="https://learn.microsoft.com/en-us/assessments/b45998e4-8e92-41b1-a0bd-ab07e665db64/" target="_blank" rel="noreferrer">SAP on Azure | Well-Architected Review</a> (45 minutes, multiple choice and multiple response; question text not published)</td></tr><tr><td>Framework version</td><td>SAP on Azure guidance on Microsoft Learn, current; ARM <code>Microsoft.Workloads</code> REST reference, API versions 2023-04-01 and 2024-09-01</td></tr><tr><td>Extraction date</td><td>2026-11-25</td></tr><tr><td>Verification method</td><td>Each source page below was fetched in full with the Microsoft Learn MCP <code>microsoft_docs_fetch</code> tool on 2026-11-25, except [NW], which was read only as a search excerpt. Every ARM property an automated item reads was checked against the <code>Microsoft.Workloads</code> REST reference pages (virtual instance, central instance, database instance, application server instance, monitor). The properties were not exercised against a live SAP estate.</td></tr></tbody></table><h2 id="the-one-thing-this-enumeration-is-not" tabindex="-1">The one thing this enumeration is NOT <a class="header-anchor" href="#the-one-thing-this-enumeration-is-not" aria-label="Permalink to &quot;The one thing this enumeration is NOT&quot;">​</a></h2><p><strong>It is not Microsoft&#39;s question list.</strong> The assessment&#39;s questions are not published, and the Well-Architected SAP workload pages (<code>well-architected/sap/*</code>) now redirect to the SAP on Azure product documentation. The items below are <strong>Scout&#39;s</strong> reading of the live SAP guidance, and the <code>WAF-SAP-*</code> IDs are Scout&#39;s.</p><p>Sources:</p><ul><li>[DC] <a href="https://learn.microsoft.com/azure/sap/workloads/deployment-checklist" target="_blank" rel="noreferrer">SAP workload planning and deployment checklist</a></li><li>[AZ] <a href="https://learn.microsoft.com/azure/sap/workloads/high-availability-zones" target="_blank" rel="noreferrer">SAP workload configurations with Azure Availability Zones</a></li><li>[AMS] <a href="https://learn.microsoft.com/azure/sap/monitor/about-azure-monitor-sap-solutions" target="_blank" rel="noreferrer">What is Azure Monitor for SAP solutions?</a></li><li>[VIS] Microsoft.Workloads REST reference: <a href="https://learn.microsoft.com/rest/api/workloads/sap-virtual-instances/get" target="_blank" rel="noreferrer">SAP Virtual Instances</a>, <a href="https://learn.microsoft.com/rest/api/workloads/sap-central-instances/get" target="_blank" rel="noreferrer">Central Instances</a>, <a href="https://learn.microsoft.com/rest/api/workloads/sap-database-instances/get" target="_blank" rel="noreferrer">Database Instances</a>, <a href="https://learn.microsoft.com/rest/api/workloads/sap-application-server-instances/get" target="_blank" rel="noreferrer">Application Server Instances</a>, <a href="https://learn.microsoft.com/rest/api/workloads/monitors/get" target="_blank" rel="noreferrer">Monitors</a></li><li>[HUB] <a href="https://learn.microsoft.com/azure/sap/get-started" target="_blank" rel="noreferrer">SAP on Azure documentation</a> (the page <code>well-architected/sap/get-started</code> redirects to)</li><li>[NW] <a href="https://learn.microsoft.com/azure/architecture/guide/sap/sap-netweaver" target="_blank" rel="noreferrer">Run SAP NetWeaver in Windows on Azure</a> (search excerpt only)</li></ul><h2 id="how-scout-recognises-an-sap-estate" tabindex="-1">How Scout recognises an SAP estate <a class="header-anchor" href="#how-scout-recognises-an-sap-estate" aria-label="Permalink to &quot;How Scout recognises an SAP estate&quot;">​</a></h2><p>ARM has no &quot;this VM runs SAP&quot; flag. The one first-party signal is a <strong>Virtual Instance for SAP solutions</strong> (<code>Microsoft.Workloads/sapVirtualInstances</code>) and its <code>centralInstances</code>, <code>databaseInstances</code> and <code>applicationInstances</code> children, which Azure Center for SAP solutions creates when a system is deployed or registered. Those types are indexed by Azure Resource Graph.</p><p>Scout reads them from the universal discovery index (<code>$.discovery.Resources[*]</code>), which keeps the Resource Graph row of every discovered resource. No SAP-specific projection exists yet.</p><ul><li>Automated items are <strong>gated</strong> on those rows. An estate with no registered SAP system reports them Not assessed, never passed.</li><li>An SAP estate that is <strong>not</strong> registered with Azure Center for SAP solutions is also reported Not assessed for the automated items. The manual items stay answerable through the questionnaire.</li><li>VM-level automated items join the VM ids that the instances list in <code>vmDetails[].virtualMachineId</code>, so they only ever score machines Azure itself says belong to a registered SAP system.</li></ul><h2 id="the-enumeration-—-38-items-across-the-five-pillars" tabindex="-1">The enumeration — 38 items across the five pillars <a class="header-anchor" href="#the-enumeration-—-38-items-across-the-five-pillars" aria-label="Permalink to &quot;The enumeration — 38 items across the five pillars&quot;">​</a></h2><h3 id="reliability-waf-sap-re-—-8-items" tabindex="-1">Reliability (WAF-SAP-RE) — 8 items <a class="header-anchor" href="#reliability-waf-sap-re-—-8-items" aria-label="Permalink to &quot;Reliability (WAF-SAP-RE) — 8 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-SAP-RE-01</td><td>SAP VMs are deployed to availability zones in zone-capable regions</td><td>✅ instance VM → VM with no zone in a zone-capable region</td><td>AZ, DC</td></tr><tr><td>WAF-SAP-RE-02</td><td>Production systems have an HA design for central services and the database</td><td>❌ Manual — production virtual instances attached</td><td>AZ, DC</td></tr><tr><td>WAF-SAP-RE-03</td><td>Registered SAP systems and central services report healthy</td><td>✅ <code>health</code> of Unhealthy or Degraded</td><td>VIS</td></tr><tr><td>WAF-SAP-RE-04</td><td>No SAP system is stuck in a failed deployment, installation or registration state</td><td>✅ <code>state</code> ending in Failed</td><td>VIS</td></tr><tr><td>WAF-SAP-RE-05</td><td>Failover clusters use a Standard SKU load balancer</td><td>✅ instance load balancer → Basic SKU load balancer</td><td>AZ, DC</td></tr><tr><td>WAF-SAP-RE-06</td><td>SAP VMs have an Azure Backup protected item</td><td>✅ instance VM → no protected item</td><td>DC</td></tr><tr><td>WAF-SAP-RE-07</td><td>Cross-region disaster recovery is designed and rehearsed</td><td>❌ Manual</td><td>DC</td></tr><tr><td>WAF-SAP-RE-08</td><td>Failover, backup and restore were tested and meet the recovery objectives</td><td>❌ Manual</td><td>DC</td></tr></tbody></table><h3 id="security-waf-sap-se-—-9-items" tabindex="-1">Security (WAF-SAP-SE) — 9 items <a class="header-anchor" href="#security-waf-sap-se-—-9-items" aria-label="Permalink to &quot;Security (WAF-SAP-SE) — 9 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-SAP-SE-01</td><td>No network virtual appliance in the path between the SAP application and database layers</td><td>❌ Manual</td><td>DC</td></tr><tr><td>WAF-SAP-SE-02</td><td>Application and database layers share a virtual network (or directly peered ones) with scoped NSG and ASG rules</td><td>❌ Manual</td><td>DC</td></tr><tr><td>WAF-SAP-SE-03</td><td>SAP VMs accept no unplanned inbound traffic from the internet</td><td>❌ Manual — internet-open NSG rules attached</td><td>DC, NW</td></tr><tr><td>WAF-SAP-SE-04</td><td>Disk and storage encryption follows the SAP-specific rules</td><td>❌ Manual — disk encryption sets attached</td><td>DC</td></tr><tr><td>WAF-SAP-SE-05</td><td>Database-native encryption protects DBMS data and backups</td><td>❌ Manual</td><td>DC</td></tr><tr><td>WAF-SAP-SE-06</td><td>Azure RBAC separates SAP Basis, network and platform duties</td><td>❌ Manual</td><td>DC</td></tr><tr><td>WAF-SAP-SE-07</td><td>Microsoft Defender for Servers is enabled</td><td>✅ Defender plan tier (per subscription); Scout&#39;s reading of the security-concept and hardening items</td><td>DC</td></tr><tr><td>WAF-SAP-SE-08</td><td>SAP VMs are assessed for operating-system updates automatically</td><td>✅ instance VM → VM <code>assessmentMode</code></td><td>DC</td></tr><tr><td>WAF-SAP-SE-09</td><td>Storage accounts that back SAP shared file systems have a private endpoint</td><td>✅ attached storage account → private endpoint</td><td>DC</td></tr></tbody></table><h3 id="cost-optimization-waf-sap-co-—-4-items" tabindex="-1">Cost optimization (WAF-SAP-CO) — 4 items <a class="header-anchor" href="#cost-optimization-waf-sap-co-—-4-items" aria-label="Permalink to &quot;Cost optimization (WAF-SAP-CO) — 4 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-SAP-CO-01</td><td>Non-production SAP systems are shut down when not needed</td><td>❌ Manual — non-production virtual instances attached</td><td>DC</td></tr><tr><td>WAF-SAP-CO-02</td><td>Stable production systems use reservations or savings plans</td><td>❌ Manual — reservations attached</td><td>DC</td></tr><tr><td>WAF-SAP-CO-03</td><td>Sizing is reviewed continuously against measured utilisation</td><td>❌ Manual</td><td>DC</td></tr><tr><td>WAF-SAP-CO-04</td><td>Azure cost is reviewed per SAP system under an owned FinOps practice</td><td>❌ Manual</td><td>DC, HUB</td></tr></tbody></table><h3 id="operational-excellence-waf-sap-oe-—-10-items" tabindex="-1">Operational excellence (WAF-SAP-OE) — 10 items <a class="header-anchor" href="#operational-excellence-waf-sap-oe-—-10-items" aria-label="Permalink to &quot;Operational excellence (WAF-SAP-OE) — 10 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-SAP-OE-01</td><td>Azure Monitor for SAP solutions is deployed</td><td>✅ monitor resource exists</td><td>AMS, DC</td></tr><tr><td>WAF-SAP-OE-02</td><td>No monitor resource is in a failed provisioning state</td><td>✅ <code>provisioningState</code></td><td>AMS, VIS</td></tr><tr><td>WAF-SAP-OE-03</td><td>Monitor providers cover the OS, database, NetWeaver and cluster layers</td><td>❌ Manual — monitors attached; provider instances are not collected</td><td>AMS</td></tr><tr><td>WAF-SAP-OE-04</td><td>Deployment and configuration are automated</td><td>❌ Manual</td><td>DC</td></tr><tr><td>WAF-SAP-OE-05</td><td>Azure-specific SAP quality checks are run and acted on</td><td>❌ Manual — virtual instances attached</td><td>DC</td></tr><tr><td>WAF-SAP-OE-06</td><td>A playbook exists for planned Azure maintenance events</td><td>❌ Manual — maintenance configurations attached</td><td>DC</td></tr><tr><td>WAF-SAP-OE-07</td><td>Timeout and operating-system settings follow the Azure guidance</td><td>❌ Manual</td><td>DC</td></tr><tr><td>WAF-SAP-OE-08</td><td>Alerts and Service Health notifications cover the SAP landscape</td><td>❌ Manual — activity-log alert rules attached</td><td>DC, AMS</td></tr><tr><td>WAF-SAP-OE-09</td><td>No update installation has failed on an SAP VM</td><td>✅ instance VM → failed patch installation</td><td>DC</td></tr><tr><td>WAF-SAP-OE-10</td><td>Support prerequisites and supported release combinations are reviewed on a cadence</td><td>❌ Manual</td><td>DC</td></tr></tbody></table><h3 id="performance-efficiency-waf-sap-pe-—-7-items" tabindex="-1">Performance efficiency (WAF-SAP-PE) — 7 items <a class="header-anchor" href="#performance-efficiency-waf-sap-pe-—-7-items" aria-label="Permalink to &quot;Performance efficiency (WAF-SAP-PE) — 7 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>WAF-SAP-PE-01</td><td>SAP VMs have no Standard HDD data disks</td><td>✅ instance VM → VM with a Standard_LRS data disk</td><td>DC</td></tr><tr><td>WAF-SAP-PE-02</td><td>SAP VMs have no Standard HDD operating-system disk (Scout extends the HDD guidance to OS disks)</td><td>✅ instance VM → VM with a Standard_LRS OS disk</td><td>DC</td></tr><tr><td>WAF-SAP-PE-03</td><td>Production database storage uses Premium SSD, Premium SSD v2, Ultra Disk or NetApp Files</td><td>❌ Manual</td><td>DC</td></tr><tr><td>WAF-SAP-PE-04</td><td>Disk striping, caching and Write Accelerator follow the DBMS guidance</td><td>❌ Manual</td><td>DC</td></tr><tr><td>WAF-SAP-PE-05</td><td>Accelerated networking is enabled on every network interface of every SAP VM</td><td>✅ instance VM → network interface with it off</td><td>DC, AZ</td></tr><tr><td>WAF-SAP-PE-06</td><td>Application-to-database latency was measured and is in an acceptable range</td><td>❌ Manual</td><td>DC, AZ</td></tr><tr><td>WAF-SAP-PE-07</td><td>VM sizes are SAP-certified, sized from measured demand, and tested against throughput limits</td><td>❌ Manual</td><td>DC</td></tr></tbody></table><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pillar</th><th>Items</th><th>Automated (✅)</th><th>Manual (❌)</th></tr></thead><tbody><tr><td>Reliability</td><td>8</td><td>5</td><td>3</td></tr><tr><td>Security</td><td>9</td><td>3</td><td>6</td></tr><tr><td>Cost optimization</td><td>4</td><td>0</td><td>4</td></tr><tr><td>Operational excellence</td><td>10</td><td>3</td><td>7</td></tr><tr><td>Performance efficiency</td><td>7</td><td>3</td><td>4</td></tr><tr><td><strong>Total</strong></td><td><strong>38</strong></td><td><strong>14</strong></td><td><strong>24</strong></td></tr></tbody></table><h2 id="what-is-not-covered" tabindex="-1">What is not covered <a class="header-anchor" href="#what-is-not-covered" aria-label="Permalink to &quot;What is not covered&quot;">​</a></h2><ul><li><strong>Anything inside the SAP application or the database</strong> — kernel parameters, HANA system replication state, cluster configuration, SAP notes, interface inventory — is not visible to ARM. Those items are manual by nature.</li><li><strong>SAP HANA on Azure Large Instances</strong> is a different offering and is not scored here.</li><li><strong>SAP systems that are not registered with Azure Center for SAP solutions</strong> are invisible to the automated items (see above). A dedicated <code>domains.sap</code> projection and an image-based fallback (<code>RHEL-SAP</code>, <code>sles-sap</code> Marketplace offers) would extend coverage; neither exists yet.</li><li><strong>Provider instances</strong> under Azure Monitor for SAP solutions are not in Resource Graph, so the providers a monitor carries are checked manually (WAF-SAP-OE-03).</li><li>Several automated items read <strong>estate-wide</strong> data (Defender plans, Basic load balancers) and therefore flag a subscription or load balancer, not only the SAP machines in it; the rule text says so.</li></ul>',28)])])}const p=e(s,[["render",o]]);export{A as __pageData,p as default};
